/* =============================================================================
   MSG-01 · Panel de contenido — estilos de pantalla.
   Solo tokens del design-system: ningún hex/rgb suelto. El HTML aprobado usa
   blanco puro para texto sobre primary; el sistema no define un token blanco,
   así que se usa el crema claro más cercano (`--bw-warm-cream`).
   ========================================================================== */

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
}

.pageTitle {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
}

.pageSub {
  margin: 0 0 16px;
  max-width: 560px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.e2eeStatus {
  display: flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin: 0 0 14px;
  padding: 6px 10px;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--bw-success-dark);
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
}

.statusIcon {
  font-size: 12px;
}

.actionsBar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin: 0 0 14px;
}

.searchWrap {
  position: relative;
  flex: 0 1 300px;
  min-width: 200px;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 30px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  outline: none;
  font-family: var(--bw-font-body);
  font-size: 13px;
  color: var(--bw-deep-steel);
  background: var(--bw-surface-mist);
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
  opacity: 1;
}

.primaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  color: var(--bw-warm-cream);
  background: var(--bw-calibration-blue);
}

.primaryBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.scopeNote {
  font-size: 12px;
  line-height: 1.4;
  color: var(--bw-steel-mist);
}

.pageInfo {
  margin-left: auto;
  font-size: 12px;
  white-space: nowrap;
  color: var(--bw-input-placeholder);
}

.statusBox {
  padding: 28px 18px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-surface-mist);
  color: var(--bw-steel-mist);
  font-size: 13px;
  text-align: center;
}

.errorBox {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 14px;
  padding: 10px 14px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  font-size: 13px;
  line-height: 1.5;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-surface-mist);
  font-family: var(--bw-font-body);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
}

.pageBtn:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled {
  opacity: 0.5;
  cursor: default;
}

.pageCurrent {
  border-color: var(--bw-deep-steel);
  background: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

.pageCurrent:hover:not(:disabled) {
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
}

