import { useEffect, useState, type KeyboardEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import {
  fetchThreadPage,
  pageCount,
  type ThreadPage,
} from '../../lib/threads';
import ThreadList from './ThreadList';
import styles from './Messages.module.css';

/**
 * Devuelve el mensaje técnico de un fallo de red/PostgREST sin perder
 * `code` ni `message` (F-128). PostgREST rechaza con un objeto plano
 * `{ code, message }`, así que `String(e)` daría `[object Object]`.
 */
function describeError(e: unknown): string {
  if (typeof e === 'object' && e !== null) {
    const candidate = e as { code?: unknown; message?: unknown };
    const code = typeof candidate.code === 'string' ? candidate.code : '';
    const message = typeof candidate.message === 'string' ? candidate.message : '';
    if (code || message) return [code, message].filter(Boolean).join(': ');
    if (e instanceof Error) return e.message;
  } else if (e instanceof Error) {
    return e.message;
  }
  return String(e);
}

function pageWindow(current: number, total: number): number[] {
  const last = Math.max(1, total);
  if (last <= 5) return Array.from({ length: last }, (_, i) => i + 1);
  const start = Math.min(Math.max(1, current - 2), last - 4);
  return Array.from({ length: 5 }, (_, i) => start + i);
}

export function Messages({
  profile,
  now,
  // F-118: el shell cablea `onOpenThread` desde App.tsx, pero MSG-02 no existe
  // todavía; la prop se recibe y se ignora deliberadamente.
  onOpenThread: _onOpenThread,
}: {
  profile: MemberProfile;
  now?: Date | undefined;
  onOpenThread?: (threadId: string) => void;
}) {
  const [searchInput, setSearchInput] = useState('');
  const [term, setTerm] = useState('');
  const [page, setPage] = useState(1);
  const [pageData, setPageData] = useState<ThreadPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    setLoading(true);
    setLoadError(null);

    fetchThreadPage({ orgId: profile.orgId, search: term, page })
      .then((result) => {
        if (!active) return;
        setPageData(result);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (!active) return;
        setPageData(null);
        setLoadError(describeError(err));
        setLoading(false);
      });

    return () => {
      active = false;
    };
  }, [profile.orgId, term, page]);

  const totalPages = pageData ? pageCount(pageData.total) : 1;

  const submitSearch = () => {
    setTerm(searchInput);
    setPage(1);
  };

  const handleSearchKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      submitSearch();
    }
  };

  const showLoadedPanel = !loading && loadError === null && pageData !== null;

  return (
    <section aria-labelledby="threads-title">
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 id="threads-title" className={styles.pageTitle}>
        Hilos
      </h1>
      <p className={styles.pageSub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está
        cifrado de extremo a extremo.
      </p>

      {/*
        Estado E2EE informativo. El botón «Introducir frase de seguridad» del
        mock no existe en el MVP (CLAUDE.md §4): las claves viven en memoria de
        sesión y no hay passphrase.
      */}
      <div className={styles.e2eeStatus}>
        <i className={`ti ti-lock ${styles.statusIcon}`} aria-hidden="true" />
        E2EE activo · contenido cifrado localmente
      </div>

      <div className={styles.actionsBar}>
        <div className={styles.searchWrap}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="search"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            onKeyDown={handleSearchKeyDown}
          />
        </div>
        <button
          type="button"
          className={styles.primaryBtn}
          disabled
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span
          className={styles.scopeNote}
          data-testid="directorio-scope"
        >
          Directorio (DIR-01) · fuera del MVP
        </span>
        {showLoadedPanel && pageData !== null && (
          <span data-testid="pag-info" className={styles.pageInfo}>
            {pageData.total.toLocaleString('es-ES')} hilos · Página {page} de{' '}
            {totalPages}
          </span>
        )}
      </div>

      {loadError !== null && (
        <div role="alert" className={styles.errorBox}>
          <span>
            No se pudieron cargar los hilos. {loadError}
          </span>
        </div>
      )}

      {loading && <div className={styles.statusBox}>Cargando hilos…</div>}

      {showLoadedPanel && (
        <>
          <ThreadList
            threads={pageData?.threads ?? []}
            now={now}
            onOpen={() => {}}
          />

          <nav className={styles.pagination} aria-label="Paginación de hilos">
            <button
              type="button"
              className={styles.pageBtn}
              aria-label="Ir a la página anterior"
              disabled={page <= 1}
              onClick={() => setPage(Math.max(1, page - 1))}
            >
              ‹
            </button>
            {pageWindow(page, totalPages).map((p) => (
              <button
                key={p}
                type="button"
                className={
                  p === page
                    ? `${styles.pageBtn} ${styles.pageCurrent}`
                    : styles.pageBtn
                }
                aria-current={p === page ? 'page' : undefined}
                aria-label={`Ir a la página ${p}`}
                onClick={() => setPage(p)}
              >
                {p}
              </button>
            ))}
            <button
              type="button"
              className={styles.pageBtn}
              aria-label="Ir a la página siguiente"
              disabled={page >= totalPages}
              onClick={() => setPage(Math.min(totalPages, page + 1))}
            >
              ›
            </button>
          </nav>
        </>
      )}
    </section>
  );
}

