/* =============================================================================
   MSG-01 · Lista de hilos.
   El HTML aprobado pinta la tarjeta en blanco puro y el hover en un blanco
   azulado; el design-system no define token de blanco puro, así que la tarjeta
   usa el neutro claro más cercano (`--bw-surface-mist`) y el hover usa el tint
   de fila previsto para superficies claras (`--bw-row-hover-tint`).
   ========================================================================== */

.threadList {
  display: block;
  margin: 0;
  padding: 0;
  list-style: none;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
  background: var(--bw-surface-mist);
}

.threadRow {
  border-bottom: 1px solid var(--bw-divider-mist);
}

.threadRow:last-child {
  border-bottom: none;
}

/*
 * F-131: esta es la fila pulsable, pero el `listitem` vive en el `<li>` que la
 * envuelve. El botón va DENTRO del `<li>`, nunca con `role="button"` encima.
 */
.rowButton {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  gap: 4px 12px;
  width: 100%;
  padding: 14px 18px;
  border: none;
  background: transparent;
  font-family: var(--bw-font-body);
  text-align: left;
  cursor: pointer;
  color: inherit;
}

.rowButton:hover {
  background: var(--bw-row-hover-tint);
}

.rowButton:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--bw-calibration-blue);
}

.orgGroup {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  grid-column: 1;
  grid-row: 1;
}

.threadOrg {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.countryBadge {
  flex-shrink: 0;
  padding: 1px 6px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 2px;
  background: var(--bw-cold-white);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  white-space: nowrap;
  color: var(--bw-steel-mist);
}

.timestamp {
  grid-column: 2;
  grid-row: 1;
  justify-self: end;
  align-self: center;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  white-space: nowrap;
  color: var(--bw-input-placeholder);
}

.preview {
  grid-column: 1;
  grid-row: 2;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--bw-steel-mist);
  align-self: center;
}

.stateBadge {
  display: inline-flex;
  align-items: center;
  grid-column: 2;
  grid-row: 2;
  justify-self: end;
  padding: 2px 7px;
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  white-space: nowrap;
}

.badgeNeutral {
  border: 1px solid var(--bw-badge-neutral-border);
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
}

.badgeInfo {
  border: 1px solid var(--bw-chip-active-border);
  background: var(--bw-chip-active-bg);
  color: var(--bw-primary-dark);
}

.badgeWarn {
  border: 1px solid var(--bw-badge-warning-border);
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning-dark);
}

.badgeSuccess {
  border: 1px solid var(--bw-badge-success-border);
  background: var(--bw-badge-success-bg);
  color: var(--bw-success-dark);
}

.badgeClosed {
  border: 1px solid var(--bw-badge-neutral-border-soft);
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  text-decoration: line-through;
}

.emptyState {
  padding: 36px 24px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-surface-mist);
  text-align: center;
}

.emptyMessage {
  margin: 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.emptyAction {
  display: inline-flex;
  align-items: center;
  margin-top: 16px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  cursor: not-allowed;
  opacity: 0.6;
}

.emptyNote {
  margin: 10px 0 0;
  font-size: 12px;
  line-height: 1.5;
  color: var(--bw-steel-mist);
}

