import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Clase CSS por tono de estado. `string | undefined` es obligatorio con
 * `noUncheckedIndexedAccess`: una clase ausente del módulo no puede romper la
 * compilación, y el `?? ''` del punto de consumo la deja sin adorno.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.badgeNeutral,
  info: styles.badgeInfo,
  warn: styles.badgeWarn,
  success: styles.badgeSuccess,
  closed: styles.badgeClosed,
};

export function ThreadList({
  threads,
  now,
  onOpen,
}: {
  threads: ThreadSummary[];
  now?: Date | undefined;
  onOpen: (id: string) => void;
}) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyMessage}>
          Todavía no tienes ninguna conversación. Usa el Directorio para
          contactar con otras organizaciones.
        </p>
        <button type="button" className={styles.emptyAction} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyNote}>
          El Directorio queda fuera del MVP en esta versión.
        </p>
      </div>
    );
  }

  return (
    <ul className={styles.threadList}>
      {threads.map((thread) => {
        const toneClass = TONE_CLASS[stateTone(thread.state)] ?? '';
        return (
          <li key={thread.id} className={styles.threadRow}>
            <button
              type="button"
              className={styles.rowButton}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.orgGroup}>
                <span className={styles.threadOrg}>
                  {thread.counterpartyName}
                </span>
                {thread.counterpartyCountry !== '' && (
                  <span className={styles.countryBadge}>
                    {thread.counterpartyCountry}
                  </span>
                )}
              </span>
              <span className={styles.timestamp}>
                {relativeTime(thread.lastItemAt, now)}
              </span>
              <span className={styles.preview}>
                {previewLabel(thread.lastItem)}
              </span>
              <span className={`${styles.stateBadge} ${toneClass}`}>
                {thread.state}
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
